  document.getElementById('local-danmu-upload-status').textContent = '\u5DF2\u586B\u5145\u201C' + (resource.title || '') + '\u201D\u7684\u4FE1\u606F\uFF0C\u8BF7\u9009\u62E9\u65B0\u6587\u4EF6\u540E\u4E0A\u4F20\u3002';
